head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > getCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Column 의 ID 를 설정하여 해당 Body Cell 의 imageSrc 속성값을 반환할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 컬럼 col1~col4 는 모두 inputType=textImage + viewType=icon 이며 Column 의 imageSrc 는 즐겨찾기(빈 별) 아이콘으로 동일합니다.\n[전제] 화면 생성 시 setCellImageSrc 로 모든 Body Cell 에 Cell 단위 imageSrc 를 미리 설정해 두었으며, Cell 마다 (rowIndex + Column 순번) 조합에 따라 서로 다른 이미지가 설정되어 있습니다.\n[절차] rowIndex 와 columnInfo(Column ID) 를 선택한 뒤 getCellImageSrc 버튼을 실행하세요.\n[확인] columnInfo 를 인덱스 대신 Column ID(col1~col4) 로 지정해도 그리드에 표시된 해당 Cell 의 이미지와 리턴창의 반환값이 일치하는지 확인하세요."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (textImage Cell 에 함께 표시될 텍스트 데이터)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울", "col2": "부산", "col3": "대구", "col4": "인천" },
        { "col1": "광주", "col2": "대전", "col3": "울산", "col4": "세종" },
        { "col1": "수원", "col2": "성남", "col3": "용인", "col4": "고양" },
        { "col1": "청주", "col2": "전주", "col3": "포항", "col4": "제주" }
    ]);

    // target 생성
    //  Cell 단위 imageSrc 는 Column 의 inputType="textImage", viewType="icon" 인 경우에 유효하므로 4개 Column 모두 해당 구성으로 생성
    //  Column 단위 imageSrc 는 ico_fav.svg(빈 별) 로 동일 설정 -> Cell 단위 설정 결과가 눈에 띄도록 함
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:640px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" inputType="text" id="hcol1" value="col1 (textImage)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol2" value="col2 (textImage)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol3" value="col3 (textImage)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (textImage)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_fav.svg" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // getCellImageSrc 는 getter 이므로, 반환할 Cell 단위 imageSrc 값을 setCellImageSrc 로 미리 설정 (검증 전제)
    //  Cell 마다 서로 다른 이미지를 설정하여 Column ID 로 조회한 값이 해당 Cell 의 값인지 식별 가능하도록 구성
    let imgList = ["/img/png.png", "/img/jpg.jpg", "/img/gif.gif", "/cm/images/base/ico_fav_on.svg"];
    let colIdList = ["col1", "col2", "col3", "col4"];
    for (let r = 0; r < 4; r++) {
        for (let c = 0; c < 4; c++) {
            scwin.target1.setCellImageSrc(r, colIdList[c], imgList[(r + c) % 4]);
        }
    }
}



// getCellImageSrc 실행 : columnInfo 를 Column ID(문자열)로 지정하여 해당 Body Cell 의 imageSrc 속성값을 조회
scwin.btn_getCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // _2 : columnInfo 를 Column ID(문자열)로 그대로 전달 (Number 변환하지 않음)
    let columnInfo = par_columnInfo.getValue();

    let ret = scwin.target1.getCellImageSrc(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "getCellImageSrc(" + rowIndex + ", '" + columnInfo + "') 반환값 : " + ret);
}
